// VAmPI fixtures: the core `test` plus this pack's manifest, contract and clients, bound to the
// default credential or to any named actor (`actor('user')`). Generated by scaffold-service; edit
// freely. Specs import `test` and `expect` from here.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parse as parseYaml } from 'yaml';
import type { APIRequestContext } from '@playwright/test';
import { test as core, expect } from '../../fixtures';
import { noAuth, type AuthStrategy } from '../../helpers/auth';
import type { AuthConfig } from '../../helpers/config';
import { applyCaseMeta } from '../../helpers/case-meta';
import { loadEnvelopeCatalog, type EnvelopeCatalog } from '../../helpers/error-envelope';
import type { RedactionPolicy } from '../../helpers/redact';
import { createSchemaValidator, type SchemaValidator } from '../../helpers/schema';
import { loadService, type ServicePack } from '../../helpers/service';
import { DbInitClient } from './clients/db-init-client';
import { HomeClient } from './clients/home-client';
import { UsersClient } from './clients/users-client';
import { BooksClient } from './clients/books-client';

export function clientsFor(request: APIRequestContext, auth: AuthStrategy, service: ServicePack) {
  const redaction: RedactionPolicy = {
    identityFields: service.identity_fields,
    secretKeys: service.secret_keys,
  };
  return {
    dbInit: new DbInitClient(request, auth, redaction),
    home: new HomeClient(request, auth, redaction),
    users: new UsersClient(request, auth, redaction),
    books: new BooksClient(request, auth, redaction),
  };
}

export type VampiClients = ReturnType<typeof clientsFor>;
export type Actor = VampiClients & { name: string };

interface VampiFixtures {
  dbInit: DbInitClient;
  home: HomeClient;
  users: UsersClient;
  books: BooksClient;
  /** The pack's clients bound to a named credential: `default`, `anonymous` or one of the pack's qa-config `actors`. */
  actor: (name: string) => Promise<Actor>;
  caseMeta: void;
}

interface VampiWorkerFixtures {
  service: ServicePack;
  contract: SchemaValidator;
  envelopes: EnvelopeCatalog;
  /** Registers the user behind every `login` credential of this pack, once per worker. */
  accounts: void;
}

export const test = core.extend<VampiFixtures, VampiWorkerFixtures>({
  service: [
    // eslint-disable-next-line no-empty-pattern -- Playwright requires the destructuring form.
    async ({}, use) => {
      await use(loadService(__dirname));
    },
    { scope: 'worker' },
  ],
  contract: [
    async ({ service }, use) => {
      const file = join(service.dir, service.spec ?? 'openapi.json');
      const text = readFileSync(file, 'utf8');
      await use(createSchemaValidator(/\.ya?ml$/.test(file) ? parseYaml(text) : JSON.parse(text)));
    },
    { scope: 'worker' },
  ],
  envelopes: [
    async ({ service }, use) => {
      await use(loadEnvelopeCatalog(join(service.dir, 'error-envelopes.json')));
    },
    { scope: 'worker' },
  ],
  // VAmPI knows no user until one registers, so before any case logs in, the users named by the
  // pack's `login` credentials (auth and actors) are registered with the values in their variables.
  // A user that already exists answers 200 with status "fail" (VN-07): its next login proves the
  // password. The registration request carries the password; evidence masks it (redact.ts). An
  // environment with allow_writes false is never written to: its users must exist already.
  accounts: [
    async ({ qa, playwright, service }, use) => {
      if (!qa.allowWrites) {
        await use();
        return;
      }
      const context = await playwright.request.newContext({ baseURL: `${qa.baseUrl}/` });
      const users = clientsFor(context, noAuth, service).users;
      const logins = [qa.auth, ...Object.values(qa.actors)].filter(
        (auth): auth is Extract<AuthConfig, { type: 'login' }> => auth.type === 'login',
      );
      const usernames = new Set<string>();
      for (const auth of logins) {
        const username = process.env[auth.username_env] ?? '';
        if (usernames.has(username)) continue;
        usernames.add(username);
        const password = process.env[auth.password_env] ?? '';
        const response = await users.apiViewsUsersRegisterUser({
          auth: false,
          data: { username, password, email: `${username}@example.invalid` },
        });
        if (response.status() === 200) continue;
        // Workers register the same users at once, and the loser of that race answers 500 (VN-10).
        // The user counts as registered only when its credentials log in.
        const login = await users.apiViewsUsersLoginUser({
          auth: false,
          data: { username, password },
        });
        const token = ((await login.json().catch(() => null)) as { auth_token?: unknown } | null)
          ?.auth_token;
        if (typeof token !== 'string') {
          throw new Error(
            `Registering the user in ${auth.username_env} answered ${response.status()} and its ` +
              `login ${login.status()} without a token; has the database been created ` +
              '(npm run vampi:up)?',
          );
        }
      }
      await context.dispose();
      await use();
    },
    { scope: 'worker', auto: true },
  ],
  caseMeta: [
    async ({ service }, use, testInfo) => {
      await applyCaseMeta(service, testInfo);
      await use();
    },
    { auto: true },
  ],
  dbInit: async ({ request, auth, service }, use) => {
    await use(clientsFor(request, auth, service).dbInit);
  },
  home: async ({ request, auth, service }, use) => {
    await use(clientsFor(request, auth, service).home);
  },
  users: async ({ request, auth, service }, use) => {
    await use(clientsFor(request, auth, service).users);
  },
  books: async ({ request, auth, service }, use) => {
    await use(clientsFor(request, auth, service).books);
  },
  actor: async ({ actorSession, service }, use) => {
    await use(async (name) => {
      const session = await actorSession(name);
      return { name, ...clientsFor(session.request, session.auth, service) };
    });
  },
});

export { expect };
